-- 6. Storage: a path is a tenant's only under its tenant id; every legacy path stays Stellr's.
SELECT is(public.storage_object_tenant_id('c0ffee00-0000-4000-8000-0000000000b2/events/badge.png'), 'c0ffee00-0000-4000-8000-0000000000b2'::uuid, 'storage: {tenant_id}/… belongs to that tenant');
SELECT is(public.storage_object_tenant_id('00000000-0000-4000-8000-000000000001/events/badge.png'), '00000000-0000-4000-8000-000000000001'::uuid, 'storage: Stellr''s own prefix is Stellr''s');
SELECT is(public.storage_object_tenant_id('c0000000-0000-4000-8000-000000000001/1700000000000-licence.pdf'), '00000000-0000-4000-8000-000000000001'::uuid, 'storage: a legacy {member_id}/… path is Stellr''s, not mistaken for a tenant');
SELECT is(public.storage_object_tenant_id('event-artwork/iso-b-event/badge.png'), '00000000-0000-4000-8000-000000000001'::uuid, 'storage: a legacy named-prefix path is Stellr''s');
SELECT is(public.storage_object_tenant_id('c0ffee00-0000-4000-8000-0000000000b2'), '00000000-0000-4000-8000-000000000001'::uuid, 'storage: a bare tenant id with no object name is not a tenant path');
SELECT is(public.storage_object_tenant_id('C0FFEE00-0000-4000-8000-0000000000B2/x.png'), '00000000-0000-4000-8000-000000000001'::uuid, 'storage: only the canonical lower-case id counts');
SELECT is(public.storage_object_tenant_id(NULL), '00000000-0000-4000-8000-000000000001'::uuid, 'storage: NULL is Stellr''s (never NULL, so a policy cannot match it by accident)');
SET LOCAL ROLE tenant_app;
SELECT set_config('stellr.tenant_id', '00000000-0000-4000-8000-000000000001', true);
INSERT INTO iso_obs VALUES ('a', 'storage', 'other_prefix', (public.storage_object_tenant_id('c0ffee00-0000-4000-8000-0000000000b2/x.png'))::text);
RESET ROLE;
SELECT set_config('stellr.tenant_id', '', true);
SELECT is((SELECT v FROM iso_obs WHERE ctx = 'a' AND tbl = 'storage' AND chk = 'other_prefix'), 'c0ffee00-0000-4000-8000-0000000000b2',
  'storage: in Stellr''s context the canary prefix still reads as the canary''s (the definer sees every tenant), so a policy never hands it to Stellr');

SELECT * FROM finish();
ROLLBACK;
